11	  constructor(private readonly env: ContextEnvironment) {}
12	
13	  async synthesizeSnapshot(
14	    nodes: readonly ConcreteNode[],
15	    systemInstruction?: string,
16	  ): Promise<string> {
17	    const systemPrompt =
18	      systemInstruction ??
19	      `You are an expert Context Memory Manager. You will be provided with a raw transcript of older conversation turns between a user and an AI assistant.
20	Your task is to synthesize these turns into a single, dense, factual snapshot that preserves all critical context, preferences, active tasks, and factual knowledge.
21	
22	Discard conversational filler, pleasantries, and redundant back-and-forth iterations. Output ONLY the raw factual snapshot, formatted compactly. Do not include markdown wrappers, prefixes like "Here is the snapshot", or conversational elements.`;
23	
24	    let userPromptText = 'TRANSCRIPT TO SNAPSHOT:

';
25	    for (const node of nodes) {
26	      const payload = node.payload;
27	      let nodeContent = '';
28	      if (payload.text) {
29	        nodeContent = payload.text;
30	      } else if (payload.functionCall) {
31	        nodeContent = `CALL: ${payload.functionCall.name}(${JSON.stringify(payload.functionCall.args)})`;
32	      } else if (payload.functionResponse) {
33	        nodeContent = `RESPONSE: ${JSON.stringify(payload.functionResponse.response)}`;
34	      }
35	
36	      userPromptText += `[${node.type}]: ${nodeContent}
`;
37	    }
38	
39	    const response = await this.env.llmClient.generateContent({
40	      role: LlmRole.UTILITY_STATE_SNAPSHOT_PROCESSOR,
41	      modelConfigKey: { model: 'gemini-3-flash-base' },
42	      contents: [{ role: 'user', parts: [{ text: userPromptText }] }],
43	      systemInstruction: { role: 'system', parts: [{ text: systemPrompt }] },
44	      promptId: this.env.promptId,
45	      abortSignal: new AbortController().signal,
46	    });
47	
48	    const candidate = response.candidates?.[0];
49	    const textPart = candidate?.content?.parts?.[0];
50	    return textPart?.text || '';
51	  }
52	}
