18	    const env = createMockEnvironment();
19	    const processor = createStateSnapshotProcessor(
20	      'StateSnapshotProcessor',
21	      env,
22	      {
23	        target: 'incremental',
24	      },
25	    );
26	    const targets = [createDummyNode('ep1', NodeType.USER_PROMPT)];
27	    const result = await processor.process(createMockProcessArgs(targets));
28	    expect(result).toBe(targets); // Strict equality
29	  });
