31	  it('should apply a valid snapshot from the Inbox (Fast Path)', async () => {
32	    const env = createMockEnvironment();
33	    const processor = createStateSnapshotProcessor(
34	      'StateSnapshotProcessor',
35	      env,
36	      {
37	        target: 'incremental',
38	      },
