import type { ConcreteNode } from '../graph/types.js';

/**
 * Options controlling how a set of nodes is rendered into a plain-text
 * transcript for consumption by a utility LLM.
 */
export interface FormatNodesForLlmOptions {
  /**
   * The maximum number of characters permitted for a single tool (function)
   * response before it is truncated. Defaults to 2000.
   */
  maxToolResponseChars?: number;
}

const DEFAULT_MAX_TOOL_RESPONSE_CHARS = 2000;

/**
 * Truncates a string that exceeds `max` characters by keeping a prefix and a
 * suffix and replacing the elided middle with a marker describing how many
 * characters were removed.
 *
 * Format: `prefix... [TRUNCATED N chars] ...suffix`.
 */
function truncateMiddle(text: string, max: number): string {
  if (text.length <= max) {
    return text;
  }

  // Split the retained budget across the head and tail so that the total
  // preserved characters equal `max` (head gets the extra char when odd).
  const keepStart = Math.ceil(max / 2);
  const keepEnd = Math.floor(max / 2);

  const prefix = text.slice(0, keepStart);
  const suffix = keepEnd > 0 ? text.slice(text.length - keepEnd) : '';
  const removed = text.length - keepStart - keepEnd;

  return `${prefix}... [TRUNCATED ${removed} chars] ...${suffix}`;
}

/**
 * Renders an ordered list of context nodes into a compact, deterministic
 * transcript string suitable for feeding to a utility LLM.
 *
 * Each node is emitted on its own line using the shape:
 *   `[Turn N] [ROLE] [TYPE]: content`
 *
 * Where:
 *  - `N` is a 1-based turn number derived from the node's `turnId` (each
 *    distinct turn id encountered increments the counter).
 *  - `ROLE` is the upper-cased node role, defaulting to `SYSTEM` when the role
 *    is undefined.
 *  - `TYPE` is the node type.
 *  - `content` is the textual payload, a `CALL: name({args})` line for function
 *    calls, or a `[SEMANTIC_WRAPPER (toolName)]: {json_response}` line for
 *    function responses (truncated when it exceeds `maxToolResponseChars`).
 */
export function formatNodesForLlm(
  nodes: readonly ConcreteNode[],
  options: FormatNodesForLlmOptions = {},
): string {
  const maxToolResponseChars =
    options.maxToolResponseChars ?? DEFAULT_MAX_TOOL_RESPONSE_CHARS;

  const turnNumbers = new Map<string, number>();
  let nextTurn = 1;
  let transcript = '';

  for (const node of nodes) {
    let turn = turnNumbers.get(node.turnId);
    if (turn === undefined) {
      turn = nextTurn++;
      turnNumbers.set(node.turnId, turn);
    }

    const role = String(node.role ?? 'SYSTEM').toUpperCase();
    const type = node.type;

    const payload = node.payload;
    let content = '';

    if (payload.text !== undefined && payload.text !== null) {
      content = payload.text;
    } else if (payload.functionCall) {
      const args = JSON.stringify(payload.functionCall.args ?? {});
      content = `CALL: ${payload.functionCall.name}(${args})`;
    } else if (payload.functionResponse) {
      const toolName = payload.functionResponse.name;
      const jsonResponse = truncateMiddle(
        JSON.stringify(payload.functionResponse.response ?? {}),
        maxToolResponseChars,
      );
      content = `[SEMANTIC_WRAPPER (${toolName})]: ${jsonResponse}`;
    }

    transcript += `[Turn ${turn}] [${role}] [${type}]: ${content}\n`;
  }

  return transcript;
}
