              turnId: snapshotId,
              type: NodeType.SNAPSHOT,
              timestamp: latest.timestamp,
              role: 'user',
              payload: { text: latest.payload.newText },
            };

            nodesToSummarize = [previousStateNode, ...targets];
          }
        }

